{
    int en = (mp_input.enable != 0) ? 1 : 0;
    const adcs_vec3_t *req_v = mp_input.request_a_m2;
    const adcs_vec3_t *fld_v = mp_input.field_body_t;
    double bnorm2;
    double sthr, pthr;
    adcs_vec3_t zero_v = {0.0, 0.0, 0.0};
    adcs_vec3_t qcap = {0.0, 0.0, 0.0};
    int i;
    double rv[3], lv[3], uv[3];

    /* 1) Disable clears all state and thermal history */
    if (!en) {
        mp_state.mode = MP_IDLE;
        mp_state.elapsed = 0U;
        mp_state.thermal_cycles = 0U;
        mp_state.recovery_count = 0U;
        mp_state.captured_a_m2 = zero_v;
        mp_state.last_capture_a_m2 = zero_v;
        mp_output.mode = mp_state.mode;
        mp_output.elapsed = mp_state.elapsed;
        mp_output.thermal_cycles = mp_state.thermal_cycles;
        mp_output.recovery_count = mp_state.recovery_count;
        mp_output.realized_a_m2 = zero_v;
        mp_output.torque_nm = zero_v;
        return;
    }

    /* 2) Validate enabled input; latch FAULT on infraction */
    {
        int bad = 0;
        if (!(mp_config.max_dipole_a_m2 > 0.0)) bad = 1;
        if (mp_config.stop_fraction <= 0.0 ||
            mp_config.stop_fraction >= mp_config.start_fraction ||
            mp_config.start_fraction > 1.0) bad = 1;
        if (mp_config.pulse_cycles < 1U || mp_config.pulse_cycles > 100U) bad = 1;
        if (mp_config.cooldown_cycles < 1U || mp_config.cooldown_cycles > 100U) bad = 1;
        if (mp_config.reversal_blank_cycles < 1U || mp_config.reversal_blank_cycles > 100U) bad = 1;
        if (mp_config.max_thermal_cycles < 1U || mp_config.max_thermal_cycles > 100U) bad = 1;
        if (mp_config.recovery_cycles < 1U || mp_config.recovery_cycles > 100U) bad = 1;
        if ((req_v == NULL) || (fld_v == NULL)) bad = 1;
        if (!bad) {
            if (!adcs_is_finite_vec3(req_v)) bad = 1;
            if (!adcs_is_finite_vec3(fld_v)) bad = 1;
        }
        if (!bad) {
            bnorm2 = adcs_vec3_dot(fld_v, fld_v);
            if (!(bnorm2 > 1.0e-12)) bad = 1;
        }
        if (bad) {
            mp_state.mode = MP_FAULT;
            mp_output.mode = mp_state.mode;
            mp_output.elapsed = mp_state.elapsed;
            mp_output.thermal_cycles = mp_state.thermal_cycles;
            mp_output.recovery_count = mp_state.recovery_count;
            mp_output.realized_a_m2 = zero_v;
            mp_output.torque_nm = zero_v;
            return;
        }
    }

    /* 3) Stay latched until disable */
    if (mp_state.mode == MP_FAULT) {
        mp_output.mode = mp_state.mode;
        mp_output.elapsed = mp_state.elapsed;
        mp_output.thermal_cycles = mp_state.thermal_cycles;
        mp_output.recovery_count = mp_state.recovery_count;
        mp_output.realized_a_m2 = zero_v;
        mp_output.torque_nm = zero_v;
        return;
    }

    sthr = mp_config.start_fraction * mp_config.max_dipole_a_m2;
    pthr = mp_config.stop_fraction * mp_config.max_dipole_a_m2;

    /* 4) Schmitt-quantize each requested axis */
    rv[0] = req_v->x; rv[1] = req_v->y; rv[2] = req_v->z;
    lv[0] = mp_state.last_capture_a_m2.x;
    lv[1] = mp_state.last_capture_a_m2.y;
    lv[2] = mp_state.last_capture_a_m2.z;
    for (i = 0; i < 3; i++) {
        int same_pol = 0;
        uv[i] = 0.0;
        if (fabs(lv[i]) > 1.0e-12 && (rv[i] * lv[i]) > 0.0) same_pol = 1;
        if (same_pol) {
            if (fabs(rv[i]) >= pthr) uv[i] = rv[i];
        } else {
            if (fabs(rv[i]) >= sthr) uv[i] = rv[i];
        }
    }
    qcap.x = uv[0]; qcap.y = uv[1]; qcap.z = uv[2];

    {
        adcs_vec3_t emit = zero_v;
        int all_below = 1;

        for (i = 0; i < 3; i++) {
            if (fabs(rv[i]) >= pthr) { all_below = 0; break; }
        }

        switch (mp_state.mode) {
        case MP_IDLE:
            if (qcap.x != 0.0 || qcap.y != 0.0 || qcap.z != 0.0) {
                mp_state.captured_a_m2 = qcap;
                if (mp_state.last_capture_a_m2.x != 0.0 ||
                    mp_state.last_capture_a_m2.y != 0.0 ||
                    mp_state.last_capture_a_m2.z != 0.0) {
                    double d = adcs_vec3_dot(&qcap, &mp_state.last_capture_a_m2);
                    if (d < 0.0) {
                        mp_state.mode = MP_REVERSAL_WAIT;
                        mp_state.elapsed = 0U;
                        emit = zero_v;
                        break;
                    }
                }
                mp_state.mode = MP_PULSE;
                mp_state.elapsed = 1U;
                mp_state.thermal_cycles += 1U;
                mp_state.last_capture_a_m2 = qcap;
                emit = qcap;
                if (mp_state.thermal_cycles >= mp_config.max_thermal_cycles) {
                    mp_state.mode = MP_INHIBIT;
                    mp_state.elapsed = 0U;
                    emit = zero_v;
                }
            } else {
                emit = zero_v;
            }
            break;

        case MP_PULSE:
            emit = mp_state.captured_a_m2;
            mp_state.thermal_cycles += 1U;
            if (mp_state.thermal_cycles >= mp_config.max_thermal_cycles) {
                mp_state.mode = MP_INHIBIT;
                mp_state.elapsed = 0U;
                emit = zero_v;
            } else if (all_below) {
                mp_state.mode = MP_COOLDOWN;
                mp_state.elapsed = 0U;
            } else {
                mp_state.elapsed += 1U;
                if (mp_state.elapsed >= mp_config.pulse_cycles) {
                    mp_state.mode = MP_COOLDOWN;
                    mp_state.elapsed = 0U;
                }
            }
            break;

        case MP_COOLDOWN:
            mp_state.elapsed += 1U;
            emit = zero_v;
            if (mp_state.elapsed >= mp_config.cooldown_cycles) {
                mp_state.mode = MP_IDLE;
                mp_state.elapsed = 0U;
            }
            break;

        case MP_REVERSAL_WAIT:
            mp_state.elapsed += 1U;
            emit = zero_v;
            if (mp_state.elapsed >= mp_config.reversal_blank_cycles) {
                mp_state.mode = MP_IDLE;
                mp_state.elapsed = 0U;
                mp_state.last_capture_a_m2 = zero_v;
            }
            break;

        case MP_INHIBIT:
            emit = zero_v;
            if (all_below) {
                mp_state.recovery_count += 1U;
                if (mp_state.recovery_count >= mp_config.recovery_cycles) {
                    mp_state.mode = MP_IDLE;
                    mp_state.elapsed = 0U;
                    mp_state.thermal_cycles = 0U;
                    mp_state.recovery_count = 0U;
                }
            } else {
                mp_state.recovery_count = 0U;
            }
            break;

        default:
            mp_state.mode = MP_IDLE;
            emit = zero_v;
            break;
        }

        mp_output.mode = mp_state.mode;
        mp_output.elapsed = mp_state.elapsed;
        mp_output.thermal_cycles = mp_state.thermal_cycles;
        mp_output.recovery_count = mp_state.recovery_count;
        mp_output.realized_a_m2 = emit;
        mp_output.torque_nm = adcs_vec3_cross(&emit, fld_v);
    }
}

