        cap[0] = 0.0; cap[1] = 0.0; cap[2] = 0.0;
        last[0] = mp_state.last_capture_a_m2.x;
        last[1] = mp_state.last_capture_a_m2.y;
        last[2] = mp_state.last_capture_a_m2.z;
        for (i = 0; i < 3; i++) {
            double mag = fabs(rc[i]);
            int same = 0;
            if (rc[i] > 0.0 && last[i] > 0.0) same = 1;
            if (rc[i] < 0.0 && last[i] < 0.0) same = 1;
            if (mag >= on_thresh) {
                cap[i] = (rc[i] >= 0.0) ? mp_config.max_dipole_a_m2
                                        : -mp_config.max_dipole_a_m2;
            } else if (same && mag >= off_thresh) {
                cap[i] = (rc[i] >= 0.0) ? mp_config.max_dipole_a_m2
                                        : -mp_config.max_dipole_a_m2;
            } else {
                cap[i] = 0.0;
            }
        }
        mp_state.captured_a_m2 = (adcs_vec3_t){cap[0], cap[1], cap[2]};

        if (cap[0] != 0.0 || cap[1] != 0.0 || cap[2] != 0.0) {
            int opposing = 0;
            int nonzero_last = 0;
            for (i = 0; i < 3; i++) {
                if (last[i] != 0.0) {
                    nonzero_last = 1;
                    if ((cap[i] > 0.0 && last[i] < 0.0) ||
                        (cap[i] < 0.0 && last[i] > 0.0))
                        opposing = 1;
                }
            }
            if (nonzero_last && opposing) {
                mp_state.mode = MP_REVERSAL_WAIT;
                mp_state.elapsed = 0U;
                realized = (adcs_vec3_t){0.0, 0.0, 0.0};
            } else {
                mp_state.thermal_cycles += 1U;
                if (mp_state.thermal_cycles >= mp_config.max_thermal_cycles) {
                    mp_state.mode = MP_INHIBIT;
                    realized = (adcs_vec3_t){0.0, 0.0, 0.0};
                } else {
                    mp_state.mode = MP_PULSE;
                    mp_state.elapsed = 1U;
                    realized = mp_state.captured_a_m2;
                }
            }
        } else {
            realized = (adcs_vec3_t){0.0, 0.0, 0.0};
        }
        break;
    }
    case MP_PULSE: {
        int all_below = 1;
        for (i = 0; i < 3; i++) {
            if (fabs(rc[i]) >= off_thresh) {
                all_below = 0;
                break;
            }
        }
        if (all_below) {
            mp_state.mode = MP_COOLDOWN;
            mp_state.elapsed = 0U;
            realized = (adcs_vec3_t){0.0, 0.0, 0.0};
        } else {
            mp_state.thermal_cycles += 1U;
            if (mp_state.thermal_cycles >= mp_config.max_thermal_cycles) {
                mp_state.mode = MP_INHIBIT;
                realized = (adcs_vec3_t){0.0, 0.0, 0.0};
            } else if ((mp_state.elapsed + 1U) >= mp_config.pulse_cycles) {
                realized = mp_state.captured_a_m2;
                mp_state.mode = MP_COOLDOWN;
                mp_state.elapsed = 0U;
            } else {
                mp_state.elapsed += 1U;
                realized = mp_state.captured_a_m2;
            }
        }
        break;
    }
    case MP_REVERSAL_WAIT: {
        realized = (adcs_vec3_t){0.0, 0.0, 0.0};
        mp_state.elapsed += 1U;
        if (mp_state.elapsed >= mp_config.reversal_blank_cycles) {
            mp_state.mode = MP_IDLE;
            mp_state.elapsed = 0U;
            mp_state.last_capture_a_m2 = (adcs_vec3_t){0.0, 0.0, 0.0};
        }
        break;
    }
    case MP_COOLDOWN: {
        realized = (adcs_vec3_t){0.0, 0.0, 0.0};
        mp_state.elapsed += 1U;
        if (mp_state.elapsed >= mp_config.cooldown_cycles) {
            mp_state.mode = MP_IDLE;
            mp_state.elapsed = 0U;
        }
        break;
    }
    case MP_INHIBIT: {
        int any_above = 0;
        realized = (adcs_vec3_t){0.0, 0.0, 0.0};
        for (i = 0; i < 3; i++) {
            if (fabs(rc[i]) >= off_thresh) {
                any_above = 1;
                break;
            }
        }
        if (any_above) {
            mp_state.recovery_count = 0U;
        } else {
            mp_state.recovery_count += 1U;
            if (mp_state.recovery_count >= mp_config.recovery_cycles) {
                mp_state.mode = MP_IDLE;
                mp_state.elapsed = 0U;
                mp_state.thermal_cycles = 0U;
                mp_state.recovery_count = 0U;
                mp_state.captured_a_m2 = (adcs_vec3_t){0.0, 0.0, 0.0};
            }
        }
        break;
    }
    default:
        break;
    }

    torque = adcs_vec3_cross(&realized, fld);

    mp_output.mode = mp_state.mode;
    mp_output.elapsed = mp_state.elapsed;
    mp_output.thermal_cycles = mp_state.thermal_cycles;
    mp_output.recovery_count = mp_state.recovery_count;
    mp_output.realized_a_m2 = realized;
    mp_output.torque_nm = torque;
}
